<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;
use App\Modules\CommercialRental\Services\CommercialRentalCategoryService;
final class CommercialRentalCategoryController extends Controller{private CommercialRentalCategoryService$s;private Authorization$a;public function __construct(){$this->s=new CommercialRentalCategoryService();$this->a=new Authorization();}private function ok(string$p,string$r='/commercial-rentals/categories'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException$e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->ok('commercial_rental.categories.view'))return;$this->view('CommercialRental::Categories.index',['title'=>'Vehicle Categories','categories'=>$this->s->all((int)Auth::tenantId())]);}public function create():void{if(!$this->ok('commercial_rental.categories.create'))return;$this->view('CommercialRental::Categories.create',['title'=>'Add Vehicle Category']);}public function store():void{if(!$this->ok('commercial_rental.categories.create'))return;try{$this->s->create((int)Auth::tenantId(),$_POST,(int)Auth::id());flash('success','Category created.');redirect('/commercial-rentals/categories');}catch(Throwable$e){$this->view('CommercialRental::Categories.create',['title'=>'Add Vehicle Category','error'=>$e->getMessage(),'old'=>$_POST]);}}public function edit(int$id):void{if(!$this->ok('commercial_rental.categories.edit'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Categories.edit',['title'=>'Edit Vehicle Category','record'=>$r]);}public function update(int$id):void{if(!$this->ok('commercial_rental.categories.edit'))return;try{$this->s->update((int)Auth::tenantId(),$id,$_POST,(int)Auth::id());flash('success','Category updated.');redirect('/commercial-rentals/categories');}catch(Throwable$e){$this->view('CommercialRental::Categories.edit',['title'=>'Edit Vehicle Category','record'=>$_POST,'error'=>$e->getMessage()]);}}public function destroy(int$id):void{if(!$this->ok('commercial_rental.categories.delete'))return;$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Category deleted.');redirect('/commercial-rentals/categories');}}
